// Crop a 2x2 (or 3-panel) mood-sheet generated by Gemini into individual
// transparent-background portraits. Each source image is a grid of panels
// on a white background with a thin border rectangle drawn around each —
// we crop well inside those borders (MARGIN) so the border line itself
// never ends up in the output, then trim() tightens to the character.
import sharp from 'sharp';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const input = process.argv[2];
const outputPrefix = process.argv[3];
if (!input || !outputPrefix) {
  console.error('Usage: node scripts/process-monster-sheet.mjs <source.png> <outputPrefix>');
  console.error('Example: node scripts/process-monster-sheet.mjs ~/Downloads/monster1.png monster-normal');
  process.exit(1);
}

const THRESHOLD = 238; // pixels with R,G,B all >= this become transparent
const MARGIN = 140; // inward margin from each quadrant's outer edge / shared midline

// quadrant key -> { region, mood }. Adjust per source image after inspecting it.
const QUADRANTS = {
  happy: 'top-left',
  sad: 'top-right',
  urgent: 'bottom-right',
};

async function run() {
  const meta = await sharp(input).metadata();
  const { width, height } = meta;
  const halfW = Math.floor(width / 2);
  const halfH = Math.floor(height / 2);

  const REGIONS = {
    'top-left': { left: MARGIN, top: MARGIN, width: halfW - MARGIN * 2, height: halfH - MARGIN * 2 },
    'top-right': { left: halfW + MARGIN, top: MARGIN, width: width - halfW - MARGIN * 2, height: halfH - MARGIN * 2 },
    'bottom-left': { left: MARGIN, top: halfH + MARGIN, width: halfW - MARGIN * 2, height: height - halfH - MARGIN * 2 },
    'bottom-right': { left: halfW + MARGIN, top: halfH + MARGIN, width: width - halfW - MARGIN * 2, height: height - halfH - MARGIN * 2 },
  };

  for (const [mood, quadrant] of Object.entries(QUADRANTS)) {
    const region = REGIONS[quadrant];
    const output = join(__dirname, '../public/monster-dessert', `${outputPrefix}-${mood}.png`);

    const { data, info } = await sharp(input)
      .extract(region)
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });

    const { width: w, height: h, channels } = info;
    for (let i = 0; i < data.length; i += channels) {
      const r = data[i], g = data[i + 1], b = data[i + 2];
      if (r >= THRESHOLD && g >= THRESHOLD && b >= THRESHOLD) data[i + 3] = 0;
    }

    await sharp(data, { raw: { width: w, height: h, channels } })
      .png()
      .trim()
      .toFile(output);

    console.log(`Done! ${mood} (${quadrant}) → ${output}`);
  }
}

run();
